/// <summary>
/// Modify route details dialog class
/// </summary>
class METShipmentUpdateRoutesDialog extends RunBase
{
    DialogField     metRoute;
    DialogFIeld     metRouteStopNum;
    DialogField     confirmedShipDate;

    METRoute        metRouteValue;
    METRouteStopNum metRouteStopNumValue;
    SalesShippingDateConfirmed  confirmedShipDateValue;
    Args            args;
    METOrderTransactionType orderTransactionType;

}

Method.Source:
/// <summary>
/// Generate dialog class
/// </summary>
/// <returns>Object</returns>
public Object Dialog()
{
    Dialog dialog;

    dialog = super();

    dialog.caption( "@MET:RouteChange");

    metRoute            = dialog.addField( extendedTypeStr(METRoute), "@MET:ChangePrimarRouteTo");
    metRouteStopNum     = dialog.addField( extendedTypeStr(METRouteStopNum), "@MET:ChangeRouteStopTo");
    confirmedShipDate   = dialog.addField( extendedTypeStr(SalesShippingDateConfirmed), "@MET:ChangeShipDateTo");

    dialog.formBuildDesign().dialogSize(0);

    return dialog;
}

/// <summary>
/// Get the values from dialog
/// </summary>
/// <returns>Boolean values</returns>
public boolean getFromDialog()
{
    metRouteValue           = metRoute.value();
    metRouteStopNumValue    = metRouteStopNum.value();
    confirmedShipDateValue  = confirmedShipDate.value();

    return super();
}

/// <summary>
/// Parameter args method
/// </summary>
/// <param name = "_args">Args reference</param>
/// <returns>Args</returns>
public Args parmArgs(Args   _args = args)
{
    args = _args;

    return args;
}

/// <summary>
/// Order transaction type parameter
/// </summary>
/// <param name = "_orderTransactionType">Order transaction type</param>
/// <returns>METOrderTransactionType</returns>
public METOrderTransactionType parmOrderType(METOrderTransactionType        _orderTransactionType = orderTransactionType)
{
    orderTransactionType = _orderTransactionType;

    return orderTransactionType;
}

/// <summary>
/// Run method for business logic
/// </summary>
public void run()
{
    METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeader;
    METSalesOrderShipmentLoadLines      metSalesOrderShipmentLoadLines;
    FormRun                             formRun = this.parmArgs().caller();
    Map                                 map;
    MapIterator                         mapIterator;

    if (args.dataset() == tableNum(METSalesOrderShipmentLoadHeader))
    {
        try
        {
            ttsbegin;
            map = formRun.getFinalizationHeaderMap();

            orderTransactionType = formRun.getOrderTranscationType();
            mapIterator = new MapIterator (map);

            while (mapIterator.more())
            {
                metSalesOrderShipmentLoadHeader = metSalesOrderShipmentLoadHeader::findByRecId(mapIterator.key(), true);

                metSalesOrderShipmentLoadHeader.updateRouteInformation(confirmedShipDateValue, metRouteValue, metRouteStopNumValue, orderTransactionType);

                mapIterator.next();
            }

            info("@MET:UpdateShipment");
            ttscommit;
        }
        catch
        {
            exceptionTextFallThrough();
        }

    }
    else if (args.dataset() == tableNum(METSalesOrderShipmentLoadLines))
    {
        try
        {
            ttsbegin;
            map = formRun.getFinalizationLineMap();
            orderTransactionType = formRun.getOrderTranscationType();
            mapIterator = new MapIterator(map);

            while (mapIterator.more())
            {
                if (mapIterator.key() != '')
                {
                    if (orderTransactionType == METOrderTransactionType::SalesOrder)
                    {
                        METSalesOrderShipmentLoadHeader::updateSalesTableAndShipment(mapIterator.key(), confirmedShipDateValue, metRouteValue, metRouteStopNumValue);
                    }
                    else
                    {
                        METSalesOrderShipmentLoadHeader::updateTransferOrderAndShipment(mapIterator.key(), confirmedShipDateValue, metRouteValue, metRouteStopNumValue);
                    }
                }

                mapIterator.next();
            }
            info("@MET:UpdateShipment");
            ttscommit;
        }
        catch
        {
            exceptionTextFallThrough();
        }
    }
}

/// <summary>
/// Main method for the class
/// </summary>
/// <param name = "_args">Args reference</param>
public static void main(Args _args)
{
    METShipmentUpdateRoutesDialog metShipmentUpdateRoutesDialog = new METShipmentUpdateRoutesDialog();

    metShipmentUpdateRoutesDialog.parmOrderType(_args.parmEnum());

    if (metShipmentUpdateRoutesDialog.prompt())
    {
        metShipmentUpdateRoutesDialog.parmArgs(_args);
        metShipmentUpdateRoutesDialog.run();
    }
}

/// <summary>
/// Validation before processing business logic
/// </summary>
public void validateRouteDetails()
{
    if (!metRouteValue && !metRouteStopNumValue && !confirmedShipDateValue)
    {
        throw error("@MET:UpdateCancelled");
    }

    if (confirmedShipDateValue < DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()))
    {
        throw error("@MET:ShipDateNotConfirmed");
    }
}
